INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (138, 283, 'tear hair tape self adhesive tear strip', '../upload/image/20180929/20180929104337_56172.jpg', '<p></p><p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">tear hair tape self adhesive tear strip</span></strong></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Self adhesive tear tape (tear strip) are used for opening of cigarette packs, biscuit bag/boxes, chewing gum bags, medicine pieces, garments, CD, and so forth.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Tear tapes included BOPP tear tape,BOPET tear tape,adhesive tear tape ,cigarette tear tape,BOPET tear tape and other non cigarette usage tear tapes</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">1) Material of Self adhesive tear tape: BOPET, BOPP,VMOPP,VMOPP.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">2) Width of tear tape rolls: 1.2 - 8.0mm ( such as:1.6mm,1.8mm,2.0mm,2.5mm,3.0mm,4.5mm,6.0mm,8.0mm..)</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">3) Run length of tear tape rolls: 5,000 - 50,000m/spool</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">4) Color of tear tape rolls: red, gold, silver, green, blue, yellow, transparent, and so forth.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">5) Inner packing for of tear tape rolls: using cartons. Outer packing:using pallets.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">4.) others: anti-counterfeiting tear tape,lightness beam laser labels,water-transfer boardpaper,super crystal brightness cigarette tipping paper</span></p>', '2026-09-06 20:58:45');